    <script>
        // 解析贴吧评论数据
        function parseTiebaComments(text) {
            // 使用正则表达式匹配每个评论块
            // 格式: "用户名": [评论内容] [等级] [贴吧牌子] [点赞数] [楼层] [日期] [地址] {{回复数组}}
            const regex = /"([^"]+)":\s*\[([^\]]+)\](?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\{\{([\s\S]*?)\}\})?/g;
            const comments = [];
            let match;

            while ((match = regex.exec(text)) !== null) {
                const username = match[1];
                const comment = match[2].trim();

                // 解析附加信息
                const level = match[3] ? match[3].trim() : "1";
                const badge = match[4] ? match[4].trim() : "欲火焚身";
                const likes = match[5] ? match[5].trim().replace(/[^\d]/g, '') : "0";
                const floor = match[6] ? match[6].trim() : "第1楼";
                const date = match[7] ? match[7].trim() : "2024-01-01";
                const location = match[8] ? match[8].trim() : "北京";

                // 解析回复内容
                const repliesText = match[9];
                let replies = [];

                if (repliesText) {
                    // 使用正则表达式匹配回复
                    const replyRegex = /"([^"]+)":\s*\[([^\]]+)\](?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?/g;
                    let replyMatch;

                    while ((replyMatch = replyRegex.exec(repliesText)) !== null) {
                        replies.push({
                            username: replyMatch[1],
                            comment: replyMatch[2].trim(),
                            date: replyMatch[3] ? replyMatch[3].trim() : "2024-01-01",
                            likes: replyMatch[4] ? replyMatch[4].trim().replace(/[^\d]/g, '') : "0"
                        });
                    }
                }

                comments.push({
                    username, 
                    comment,
                    level,
                    badge,
                    likes: parseInt(likes) || 0,
                    floor,
                    date,
                    location,
                    replies,
                    totalReplies: replies.length + (replies.length > 3 ? Math.floor(Math.random() * 10) + 1 : 0)
                });
            }

            return comments;
        }

