                            <div class="reply-item">
                                <div class="reply-user">
                                    <span class="user-name">${reply.username}</span>
                                </div>
                                <div class="reply-text">${reply.comment}</div>
                                <div class="reply-info">
                                    <span>${reply.date}</span>
                                    <div class="like-button" onclick="toggleLike(this, ${reply.likes})">
                                        <i class="fas fa-thumbs-up"></i>
                                        <span class="like-count">${reply.likes}</span>
                                    </div>
                                </div>
                            </div>
                        `;
                    });

                    // 如果有更多回复，显示查看更多按钮
                    if (comment.totalReplies > 3) {
                        repliesHTML += `
                            <div class="view-more-replies" onclick="alert('该功能暂未开放')">
                                查看全部${comment.totalReplies}条回复
                            </div>
                        `;
                    }

                    repliesHTML += `</div>`;
                    commentHTML += repliesHTML;
                }

                commentHTML += `</div>`;
                commentElement.innerHTML = commentHTML;

                container.appendChild(commentElement);
            });
        }

        // 切换点赞状态
        function toggleLike(element, initialLikes) {
