                alert("搜索功能暂未开放");
            });

            // 检测是否为移动设备
            const isMobile = window.innerWidth <= 600;
            if (isMobile) {
                document.body.classList.add('mobile-view');
            }
        }

        // 执行处理
        processTiebaContent();

