    <script>
        // 解析贴吧评论数据
        function parseTiebaComments(text) {
            // 使用正则表达式匹配每个评论块
            // 格式: "用户名": [评论内容] [等级] [贴吧牌子] [点赞数] [楼层] [日期] [地址] {{回复数组}}
            const regex = /"([^"]+)":\s*\[([^\]]+)\](?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?(?:\s*\{\{([\s\S]*?)\}\})?/g;
